package com.astra.agent.docs

/**
 * Slot map of the bundled PowerPoint templates (app/src/main/assets/templates/ppt).
 * GENERATED by tools/prep_templates (see README): every template slide that works as a reusable layout is listed
 * with the ids of its text shapes. The engine in [PptxTemplates] clones these slides and swaps the text.
 * No Android dependency, so it can be tested on a plain JVM.
 */
internal enum class K { COVER, PAIRS, LIST, CLOSING }

/** A text shape: shape id, size in points, original font size in points, and whether the sample text was UPPERCASE. */
internal class Box(val id: Int, val w: Float, val h: Float, val fs: Float, val up: Boolean)

/** Text shape that is not content: [tok] is BLANK, TITLE, DATE, YEAR, PAGE or TXT:literal. */
internal class Deco(val id: Int, val tok: String)

/** A heading (optional) and the text box that belongs to it. */
internal class PS(val h: Box?, val b: Box)

internal class TSlide(
    val idx: Int, val kind: K, val title: Box, val sub: Box? = null, val lead: Box? = null,
    val pairs: List<PS> = emptyList(), val items: List<Box> = emptyList(), val minPairs: Int = 0,
    val multi: Boolean = false, val deco: List<Deco> = emptyList()
) {
    val minCount: Int get() = when (kind) { K.PAIRS -> minPairs.coerceAtLeast(1); K.LIST -> items.size; else -> 0 }
    val maxCount: Int get() = when (kind) { K.PAIRS -> if (multi) pairs.size * 3 else pairs.size; K.LIST -> items.size; else -> 0 }
}

internal class TplDef(val id: String, val name: String, val premium: Boolean, val file: String, val slides: List<TSlide>)

